-- Expression index for case-insensitive lookup
-- Query MUST use the same expression to hit the index
CREATE INDEX CONCURRENTLY IF NOT EXISTS {{index_name}}
  ON {{table_name}} (lower({{text_column}}));

-- Matching query
EXPLAIN ANALYZE
SELECT *
FROM {{table_name}}
WHERE lower({{text_column}}) = lower($1);

-- Anti-pattern (will NOT use the index):
-- SELECT * FROM {{table_name}} WHERE {{text_column}} ILIKE $1;
